//! Opt-in LLM judge over OpenRouter. The model reads the passage with the AI writing guide as
//! its reference and returns a labeled judgment. The judgment is informational: it is attached to
//! a report as a side channel and never enters the heuristic verdict or exit status.
//!
//! The report types and prompt code always compile. Only the HTTP client is gated behind the
//! `api-clients` feature.

#[cfg(feature = "api-clients")]
pub mod client;

use crate::config::Settings;
use crate::external::ExternalStatus;
use serde::Serialize;

pub const VENDOR: &str = "openrouter";
/// Pinned to an explicit model. The `~deepseek/deepseek-flash-latest` alias moves with releases.
pub const DEFAULT_MODEL: &str = "deepseek/deepseek-v4.1-flash";
pub const DEFAULT_BASE_URL: &str = "https://openrouter.ai/api/v1";
/// Reference text for the judge. Embedded so the packaged binary carries it.
pub const GUIDE: &str = include_str!("../../../docs/ai-writing-guide.md");

#[cfg(feature = "api-clients")]
const REQUEST_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(120);
/// Completion budget. Reasoning models spend part of it on hidden reasoning before the verdict,
/// so a small cap returns an empty completion.
#[cfg(feature = "api-clients")]
const MAX_COMPLETION_TOKENS: u32 = 25_000;
/// Upper bound on passage size, so one judgment stays within a predictable token budget.
pub const MAX_JUDGE_CHARS: usize = 60_000;

#[derive(Debug, Clone, Serialize, PartialEq)]
pub struct JudgeVerdict {
    /// One of `AI`, `HUMAN`, `MIXED`.
    pub label: String,
    /// Model-stated confidence, 0 to 100, when the reply gave one.
    pub confidence: Option<u8>,
}

#[derive(Debug, Clone, Serialize)]
pub struct JudgeReport {
    pub vendor: &'static str,
    /// Always true: this judgment never enters the heuristic verdict.
    pub informational: bool,
    pub model: String,
    pub strict_privacy: bool,
    pub status: ExternalStatus,
    pub reason: Option<String>,
    /// Whether the text was transmitted to the vendor.
    pub sent: bool,
    pub input_characters: usize,
    pub verdict: Option<JudgeVerdict>,
    /// The model's reply when no verdict line could be parsed, kept for inspection.
    pub unparsed_reply: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub provider: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub reply_text: Option<String>,
    pub prompt_tokens: Option<u64>,
    pub completion_tokens: Option<u64>,
    pub cost: Option<f64>,
}

impl JudgeReport {
    fn new(settings: &Settings, status: ExternalStatus, input_characters: usize) -> Self {
        Self {
            vendor: VENDOR,
            informational: true,
            model: settings.openrouter_model.clone(),
            strict_privacy: settings.openrouter_strict_privacy,
            status,
            reason: None,
            sent: false,
            input_characters,
            verdict: None,
            unparsed_reply: None,
            provider: None,
            reply_text: None,
            prompt_tokens: None,
            completion_tokens: None,
            cost: None,
        }
    }
}

/// Builds the (system, user) messages. The guide goes in the system message as reference material.
pub fn build_messages(passage: &str) -> (String, String) {
    let system = format!(
        "You are a careful text-forensics analyst. Your job is to judge whether a passage was written \
         by a human or generated by an AI language model. Use the reference guide below for the \
         known AI writing signals. Judge only from the passage's text. Do not assume the topic or \
         a source is genuine. Be calibrated: if the evidence is weak or mixed, say so.\n\n\
         <reference_guide>\n{GUIDE}\n</reference_guide>"
    );
    let user = format!(
        "Judge the passage below. Reply in this exact format:\n\
         VERDICT: AI | HUMAN | MIXED\n\
         CONFIDENCE: <0-100>\n\
         SIGNALS: bullet list. For each, quote the sentence and name the guide signal it matches.\n\
         AGAINST: bullet list of features that argue for the opposite verdict.\n\
         REASONING: 3-5 sentences.\n\n\
         <passage>\n{passage}\n</passage>"
    );
    (system, user)
}

/// Extracts the VERDICT and CONFIDENCE lines. Returns `None` when no verdict label is present.
pub fn parse_reply(reply: &str) -> Option<JudgeVerdict> {
    let verdict_re = regex::Regex::new(r"(?i)VERDICT\W{0,4}\b(AI|HUMAN|MIXED)\b").ok()?;
    let confidence_re = regex::Regex::new(r"(?i)CONFIDENCE\W{0,4}(\d{1,3})").ok()?;
    let label = verdict_re.captures(reply)?.get(1)?.as_str().to_uppercase();
    let confidence = confidence_re
        .captures(reply)
        .and_then(|c| c.get(1))
        .and_then(|m| m.as_str().parse::<u32>().ok())
        .map(|n| n.min(100) as u8);
    Some(JudgeVerdict { label, confidence })
}

/// Built without the `api-clients` feature: always reports, never sends.
#[cfg(not(feature = "api-clients"))]
pub fn judge(settings: &Settings, text: &str, _api_key: Option<&str>) -> JudgeReport {
    let mut report = JudgeReport::new(settings, ExternalStatus::Failed, text.chars().count());
    report.reason =
        Some("this build has no OpenRouter support; rebuild with --features api-clients".into());
    report
}

/// Runs the judgment for `text`. Never fails: every outcome is recorded in the returned report.
#[cfg(feature = "api-clients")]
pub fn judge(settings: &Settings, text: &str, api_key: Option<&str>) -> JudgeReport {
    use client::{ChatRequest, ClientError, OpenRouterClient};

    let chars = text.chars().count();
    let mut report = JudgeReport::new(settings, ExternalStatus::Failed, chars);
    let Some(key) = api_key.map(str::trim).filter(|k| !k.is_empty()) else {
        report.status = ExternalStatus::Skipped;
        report.reason = Some("OPENROUTER_API_KEY is not set".into());
        return report;
    };
    if text.trim().is_empty() {
        report.status = ExternalStatus::Skipped;
        report.reason = Some("no analyzable text; no request was sent".into());
        return report;
    }
    if chars > MAX_JUDGE_CHARS {
        let error = ClientError::Oversize {
            chars,
            limit: MAX_JUDGE_CHARS,
        };
        report.reason = Some(error.to_string());
        return report;
    }
    let client = match OpenRouterClient::new(
        key.to_string(),
        &settings.openrouter_base_url,
        REQUEST_TIMEOUT,
    ) {
        Ok(client) => client,
        Err(error) => {
            report.reason = Some(error.to_string());
            return report;
        }
    };
    let privacy = if settings.openrouter_strict_privacy {
        "zero-retention routing"
    } else {
        "routing without privacy restrictions"
    };
    eprintln!(
        "nobotrs: sending {chars} characters to OpenRouter model {} ({privacy}) (enabled with --openrouter-judge)",
        settings.openrouter_model
    );
    report.sent = true;
    let (system, user) = build_messages(text);
    let request = ChatRequest {
        model: &settings.openrouter_model,
        system: &system,
        user: &user,
        max_completion_tokens: MAX_COMPLETION_TOKENS,
        strict_privacy: settings.openrouter_strict_privacy,
    };
    match client.chat(&request) {
        Ok(reply) => {
            if let Some(model) = reply.model {
                report.model = model;
            }
            report.provider = reply.provider;
            report.prompt_tokens = reply.prompt_tokens;
            report.completion_tokens = reply.completion_tokens;
            report.cost = reply.cost;
            match parse_reply(&reply.content) {
                Some(verdict) => {
                    report.status = ExternalStatus::Ok;
                    report.verdict = Some(verdict);
                    report.reply_text = Some(reply.content);
                }
                None => {
                    report.reason = Some("reply did not contain a VERDICT line".into());
                    report.unparsed_reply = Some(reply.content);
                }
            }
        }
        Err(error) => report.reason = Some(error.to_string()),
    }
    report
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_label_and_confidence() {
        let reply = "VERDICT: AI\nCONFIDENCE: 87\nSIGNALS:\n- ...";
        assert_eq!(
            parse_reply(reply),
            Some(JudgeVerdict {
                label: "AI".into(),
                confidence: Some(87)
            })
        );
    }

    #[test]
    fn tolerates_markdown_bold_and_lowercase() {
        let reply = "**VERDICT:** mixed\n**CONFIDENCE:** 55";
        assert_eq!(
            parse_reply(reply),
            Some(JudgeVerdict {
                label: "MIXED".into(),
                confidence: Some(55)
            })
        );
    }

    #[test]
    fn missing_verdict_is_none_and_confidence_is_clamped() {
        assert_eq!(parse_reply("I cannot decide."), None);
        assert_eq!(
            parse_reply("VERDICT: HUMAN\nCONFIDENCE: 999")
                .unwrap()
                .confidence,
            Some(100)
        );
    }

    #[test]
    fn guide_is_embedded() {
        assert!(GUIDE.contains("AI writing"));
        let (system, user) = build_messages("Hello there.");
        assert!(system.contains("<reference_guide>"));
        assert!(user.contains("Hello there."));
    }
}
